package net.civeira.phylax.features.access.platformidentity.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.platformidentity.domain.PlatformIdentity;
import net.civeira.phylax.features.access.platformidentity.domain.event.PlatformIdentityEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class PlatformIdentityEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<PlatformIdentityEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final PlatformIdentity entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
